import app from 'flarum/forum/app';
import Page from 'flarum/common/components/Page';
import Button from 'flarum/common/components/Button';
import Link from 'flarum/common/components/Link';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import Placeholder from 'flarum/common/components/Placeholder';
import PageStructure from 'flarum/forum/components/PageStructure';
import IndexSidebar from 'flarum/forum/components/IndexSidebar';
import extractText from 'flarum/common/utils/extractText';
import ClubEditModal from './ClubEditModal';
import { t } from '../util';

/** /clubs: every club, biggest first, with what each is on now. */
export default class ClubsPage extends Page {
  oninit(vnode) {
    super.oninit(vnode);
    this.clubs = null;
    app.history.push('clubs', extractText(t('clubs.title')));
    app.store.find('clubs', {
      page: {
        limit: 50
      }
    }).then(clubs => {
      this.clubs = clubs;
      m.redraw();
    });
  }
  oncreate(vnode) {
    super.oncreate(vnode);
    app.setTitle(extractText(t('clubs.title')));
  }
  view() {
    return m(PageStructure, {
      className: "ClubsPage",
      sidebar: () => m(IndexSidebar, null)
    }, m("div", {
      className: "IndexPage-toolbar ClubsPage-toolbar"
    }, m("h2", null, t('clubs.title')), app.forum.attribute('canStartClub') ? m(Button, {
      className: "Button Button--primary",
      icon: "fas fa-plus",
      onclick: () => app.modal.show(ClubEditModal)
    }, t('clubs.start')) : null), this.clubs === null ? m(LoadingIndicator, {
      display: "block"
    }) : this.clubs.length ? m("ul", {
      className: "ClubCards"
    }, this.clubs.map(club => m("li", null, m(Link, {
      className: "ClubCard",
      href: app.route('club', {
        id: club.id()
      })
    }, m("span", {
      className: "ClubCard-icon",
      "aria-hidden": "true"
    }, m("i", {
      className: "fas fa-book-open-reader"
    })), m("b", null, club.name()), m("small", null, t('clubs.members', {
      count: club.memberCount()
    }), club.viewerRole() ? m('[', null, " \xB7 ", t(`clubs.role_${club.viewerRole()}`)) : null), club.description() ? m("p", null, club.description()) : null)))) : m(Placeholder, {
      text: t('clubs.none')
    }));
  }
}
flarum.reg.add('ernestdefoe-club', 'forum/components/ClubsPage', ClubsPage);